type PostRouteContext = {
  params: Promise<{ id: string }>
}

type UpdatePostBody = {
  title?: string
  content?: string
}

async function parseUpdatePostBody(
  request: Request,
): Promise<UpdatePostBody | null> {
  try {
    const body: unknown = await request.json()

    if (typeof body !== 'object' || body === null) {
      return null
    }

    const values = body as Record<string, unknown>

    return {
      title: typeof values.title === 'string' ? values.title : undefined,
      content: typeof values.content === 'string' ? values.content : undefined,
    }
  } catch {
    return null
  }
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params
  const postId = Number.parseInt(id, 10)
  const post = {
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const [{ id }, body] = await Promise.all([params, parseUpdatePostBody(request)])

  if (!body) {
    return Response.json({ error: 'Invalid request body' }, { status: 400 })
  }

  const postId = Number.parseInt(id, 10)
  const updatedPost = {
    id: postId,
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

