import type { BlogComment, BlogPost } from '../types/blog'

const API_BASE_URL = 'https://jsonplaceholder.typicode.com'

async function fetchJson<T>(url: string, revalidate: number | false): Promise<T> {
  const response = await fetch(
    url,
    revalidate === false
      ? { cache: 'no-store' }
      : { next: { revalidate } },
  )

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`)
  }

  return (await response.json()) as T
}

export function getPosts(revalidate: number | false = 60): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${API_BASE_URL}/posts`, revalidate)
}

export function getRecentPosts(): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${API_BASE_URL}/posts?_limit=5`, false)
}

export function getPost(id: string, revalidate = 300): Promise<BlogPost> {
  return fetchJson<BlogPost>(`${API_BASE_URL}/posts/${encodeURIComponent(id)}`, revalidate)
}

export function getPostComments(
  id: string,
  revalidate = 300,
): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(
    `${API_BASE_URL}/posts/${encodeURIComponent(id)}/comments`,
    revalidate,
  )
}

