import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from '../../../components/BackButton'
import { getPost, getPostComments, getPosts } from '../../../lib/blog'
import type { BlogPost } from '../../../types/blog'

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

export const revalidate = 300

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts(300)

  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params

  try {
    const post = await getPost(id)
    const description = post.body.substring(0, 160)

    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return { title: 'Post Not Found - My Blog' }
  }
}

function isBlogPost(value: unknown): value is BlogPost {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const post = value as Record<string, unknown>

  return (
    typeof post.id === 'number' &&
    typeof post.title === 'string' &&
    typeof post.body === 'string'
  )
}

export default async function BlogPostPage({
  params,
}: BlogPostPageProps) {
  const { id } = await params

  const result = await Promise.all([getPost(id), getPostComments(id)]).catch(
    () => null,
  )

  if (!result) {
    notFound()
  }

  const [post, comments] = result

  if (!isBlogPost(post) || !Array.isArray(comments)) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
type NewPost = {
  id: number
  title: string
  content: string
  createdAt: string
}

type CreatePostBody = {
  title: string
  content: string
}

async function parseCreatePostBody(request: Request): Promise<CreatePostBody | null> {
  try {
    const body: unknown = await request.json()

    if (typeof body !== 'object' || body === null) {
      return null
    }

    const { title, content } = body as Record<string, unknown>

    if (
      typeof title !== 'string' ||
      !title ||
      typeof content !== 'string' ||
      !content
    ) {
      return null
    }

    return { title, content }
  } catch {
    return null
  }
}

export async function GET(): Promise<Response> {
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: Request): Promise<Response> {
  const body = await parseCreatePostBody(request)

  if (!body) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 },
    )
  }

  const newPost: NewPost = {
    id: Date.now(),
    title: body.title,
    content: body.content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}
